<?php
require_once 'config/app.php'; $pageTitle = 'Election results'; $pdo = db(); $election = current_election();
$total = $pdo->prepare('SELECT COUNT(*) FROM ballots WHERE election_id = ?'); $total->execute([$election['id'] ?? 0]); $totalVotes = (int) $total->fetchColumn();
$registered = $pdo->prepare('SELECT COUNT(*) FROM voter_election_status WHERE election_id = ?'); $registered->execute([$election['id'] ?? 0]); $registeredVoters = (int) $registered->fetchColumn();
$offices = $pdo->prepare('SELECT * FROM offices WHERE election_id = ? ORDER BY display_order'); $offices->execute([$election['id'] ?? 0]); include 'includes/header.php';
?><div class="section-heading"><div><div class="eyebrow">Public count</div><h1><?= e($election['title'] ?? 'Election results') ?></h1></div><span class="label"><?= e($election['results_mode'] ?? 'after_close') === 'live' ? 'Live results' : 'Published after close' ?></span></div><div class="grid"><div class="panel"><div class="stat"><?= $totalVotes ?></div><div class="label">Total votes cast</div></div><div class="panel"><div class="stat"><?= $registeredVoters ?></div><div class="label">Registered voters</div></div><div class="panel"><div class="stat"><?= $registeredVoters ? round($totalVotes / $registeredVoters * 100) : 0 ?>%</div><div class="label">Turnout</div></div></div><?php foreach ($offices as $office): ?><section style="margin-top:48px"><div class="section-heading"><h2><?= e($office['name']) ?></h2></div><?php $stmt = $pdo->prepare('SELECT c.name, p.abbreviation, p.color, COUNT(bc.candidate_id) votes FROM candidates c JOIN parties p ON p.id = c.party_id LEFT JOIN ballot_choices bc ON bc.candidate_id = c.id JOIN offices o ON o.id = c.office_id WHERE c.office_id = ? GROUP BY c.id ORDER BY votes DESC, c.id'); $stmt->execute([$office['id']]); foreach ($stmt as $row): $percent = $totalVotes ? round($row['votes'] / $totalVotes * 100) : 0; ?><div class="results-row"><strong><?= e($row['name']) ?><br><span class="party"><?= e($row['abbreviation']) ?></span></strong><span><?= (int) $row['votes'] ?> votes<br><span class="party"><?= $percent ?>%</span></span><div class="bar"><span style="width:<?= $percent ?>%;background:<?= e($row['color']) ?>"></span></div></div><?php endforeach; ?></section><?php endforeach; ?><?php include 'includes/footer.php'; ?>